import requests, time, re, numpy as np, pandas as pd
import matplotlib.pyplot as plt
from scipy import stats
rng=np.random.default_rng(11)
E="https://eutils.ncbi.nlm.nih.gov/entrez/eutils/"
def fetch(acc):
    for _ in range(3):
        try:
            r=requests.get(E+"efetch.fcgi",params={"db":"nuccore","id":acc,"rettype":"fasta_cds_na","retmode":"text"},timeout=45)
            if r.status_code==200 and r.text.startswith(">"): return r.text
        except Exception: pass
        time.sleep(1.5)
    return None
def parse(txt,chrom):
    out={}; name=None; buf=[]; hdr=""
    for line in txt.split("\n"):
        if line.startswith(">"):
            if name: out[name]=("".join(buf).upper(),hdr,chrom)
            hdr=line; m=re.search(r"\[locus_tag=([^\]]+)\]",line)
            name=m.group(1) if m else line[1:40]; buf=[]
        else: buf.append(line.strip())
    if name: out[name]=("".join(buf).upper(),hdr,chrom)
    return out
ACC={"chr1":"NC_007194.1","chr2":"NC_007195.1","chr3":"NC_007196.1","chr4":"NC_007197.1",
     "chr6":"NC_007199.1","chr7":"NC_007200.1","chr8":"NC_007201.1"}
G={}
for lab,acc in ACC.items():
    t=fetch(acc)
    if t is None: print("FAILED",lab); continue
    G.update(parse(t,lab))
print("CDS loaded:",len(G),"from",sorted(set(v[2] for v in G.values())))

B="TCAG"; code={a+b+c:aa for (a,b,c),aa in zip([(a,b,c) for a in B for b in B for c in B],
  "FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG")}
syn={}
for c,a in code.items(): syn.setdefault(a,[]).append(c)
DEG={a:cs for a,cs in syn.items() if len(cs)>1 and a!="*"}
def cod(s):
    s=s[:len(s)//3*3]
    return [s[i:i+3] for i in range(0,len(s),3) if s[i:i+3] in code and code[s[i:i+3]]!="*"]
def Nc(cs):
    byaa={}
    for c in cs: byaa.setdefault(code[c],[]).append(c)
    Fs={}
    for a,l in byaa.items():
        if a not in DEG or len(l)<2: continue
        n=len(l); k=len(DEG[a]); p=np.array([l.count(c) for c in DEG[a]])/n
        Fs.setdefault(k,[]).append(max((n*np.sum(p**2)-1)/(n-1),1e-6))
    nc=2.0
    for k,base in [(2,9),(3,1),(4,5),(6,3)]:
        nc += base/(np.mean(Fs[k]) if k in Fs else (np.mean(Fs[4]) if 4 in Fs else 0.5))
    return min(nc,61.0)
def GC3(cs): return 100*np.mean([c[2] in "GC" for c in cs])
def mkw(ref):
    cnt={c:0 for c in code}
    for k in ref:
        for c in cod(G[k][0]): cnt[c]+=1
    w={}
    for a,cs in DEG.items():
        mx=max(cnt[c] for c in cs)
        for c in cs: w[c]=max(cnt[c]/mx,0.01) if mx>0 else 1.0
    return w,sum(cnt.values())
def CAI(cs,w): 
    v=[np.log(w[c]) for c in cs if c in w]
    return float(np.exp(np.mean(v))) if v else np.nan

base=[]
for k,(s,h,ch) in G.items():
    cs=cod(s)
    if len(cs)<80: continue
    base.append(dict(locus=k,chrom=ch,n=len(cs),Nc=Nc(cs),GC3=GC3(cs)))
bd=pd.DataFrame(base); print("genes scored:",len(bd))

A,Bq="AFUA_8G07210","AFUA_3G10660"
print("\n1) Chromosome composition check, is chr3 intrinsically more biased than chr8?")
c3,c8=bd[bd.chrom=="chr3"],bd[bd.chrom=="chr8"]
u=stats.mannwhitneyu(c3.Nc,c8.Nc)
print(f"   median Nc chr3={c3.Nc.median():.2f} (n={len(c3)}), chr8={c8.Nc.median():.2f} (n={len(c8)}), Mann-Whitney p={u.pvalue:.3g}")
print(f"   median GC3 chr3={c3.GC3.median():.1f}%, chr8={c8.GC3.median():.1f}%")

print("\n2) Reference-free comparison (Nc needs no reference set, so no chromosome bias)")
nA,nB=bd[bd.locus==A].Nc.iloc[0],bd[bd.locus==Bq].Nc.iloc[0]
print(f"   erg13A Nc={nA:.2f}  percentile within chr8 = {100*np.mean(c8.Nc>nA):.1f} (lower Nc = more biased)")
print(f"   erg13B Nc={nB:.2f}  percentile within chr3 = {100*np.mean(c3.Nc>nB):.1f}")
print(f"   erg13A GC3={bd[bd.locus==A].GC3.iloc[0]:.1f}%, erg13B GC3={bd[bd.locus==Bq].GC3.iloc[0]:.1f}%")

print("\n3) Chromosome-balanced, self-consistent reference set (120 lowest-Nc genes, balanced across 7 chromosomes)")
ref=[]
for ch,g in bd.groupby("chrom"): ref += list(g.nsmallest(18,"Nc").locus)
ref=[r for r in ref if r not in (A,Bq)]
w,ncod=mkw(ref); print(f"   reference genes={len(ref)} from {bd[bd.locus.isin(ref)].chrom.nunique()} chromosomes, codons={ncod}")
bd["CAI"]=[CAI(cod(G[k][0]),w) for k in bd.locus]
cA,cB=bd[bd.locus==A].CAI.iloc[0],bd[bd.locus==Bq].CAI.iloc[0]
print(f"   erg13A CAI={cA:.3f} percentile={100*np.mean(bd.CAI<cA):.1f} (within chr8 {100*np.mean(bd[bd.chrom=='chr8'].CAI<cA):.1f})")
print(f"   erg13B CAI={cB:.3f} percentile={100*np.mean(bd.CAI<cB):.1f} (within chr3 {100*np.mean(bd[bd.chrom=='chr3'].CAI<cB):.1f})")
print(f"   difference {cB-cA:+.4f} = {(cB-cA)/bd.CAI.std():+.2f} background sd (background mean {bd.CAI.mean():.3f}, sd {bd.CAI.std():.3f})")

def bootv(k,n=3000):
    cs=np.array(cod(G[k][0])); idx=rng.integers(0,len(cs),size=(n,len(cs)))
    return np.array([CAI(list(cs[i]),w) for i in idx])
vA,vB=bootv(A),bootv(Bq); d=vB-vA
p=max(2*min(np.mean(d<=0),np.mean(d>=0)),1/3000)
print(f"   paired codon bootstrap: 95% CI {np.percentile(d,2.5):+.4f} to {np.percentile(d,97.5):+.4f}, two-sided p={p:.4f}")

print("\n4) Controls")
CTRL={"AFUA_2G03700":"hmg1","AFUA_1G11230":"hmg2","AFUA_4G06890":"cyp51A","AFUA_7G03740":"cyp51B",
      "AFUA_2G07680":"sidA","AFUA_1G17190":"sidI","AFUA_6G04740":"act1","AFUA_1G10910":"tubA"}
for k,nm in CTRL.items():
    if k in set(bd.locus):
        r=bd[bd.locus==k].iloc[0]
        print(f"   {nm:7s} {r.chrom}  CAI={r.CAI:.3f} pct={100*np.mean(bd.CAI<r.CAI):.1f}  Nc={r.Nc:.1f}  GC3={r.GC3:.1f}%")
    else: print(f"   {nm:7s} locus tag not found in RefSeq CDS set")
bd["label"]=bd.locus.map({A:"erg13A",Bq:"erg13B",**CTRL}).fillna("")
bd.to_csv("erg13_codon_usage_7chrom.csv",index=False)

fig,ax=plt.subplots(1,3,figsize=(17,5))
a=ax[0]
a.hist(bd.CAI,bins=70,color="#cfcfcf")
for nm,k,c in [("erg13A",A,"#c0504d"),("erg13B",Bq,"#4f81bd")]:
    v=bd[bd.locus==k].CAI.iloc[0]; a.axvline(v,color=c,lw=2.2)
    a.text(v,a.get_ylim()[1]*0.95,nm,color=c,rotation=90,va="top",ha="right",fontsize=9)
a.set_xlabel("codon adaptation index"); a.set_ylabel("genes")
a.set_title(f"CAI against {len(bd):,} genes on 7 chromosomes",fontsize=10)
a=ax[1]
a.hist(d,bins=60,color="#9bbb59"); a.axvline(0,color="k",lw=1.5)
a.set_xlabel("CAI(erg13B) minus CAI(erg13A)"); a.set_ylabel("bootstrap replicates")
a.set_title(f"Paired codon bootstrap, p = {p:.4f}",fontsize=10)
a=ax[2]
for ch,g in bd.groupby("chrom"): a.scatter(g.GC3,g.Nc,s=3,color="#dddddd")
for nm,k,c in [("erg13A",A,"#c0504d"),("erg13B",Bq,"#4f81bd")]:
    r=bd[bd.locus==k].iloc[0]; a.scatter(r.GC3,r.Nc,s=110,color=c,edgecolor="k",zorder=5)
    a.annotate(nm,(r.GC3,r.Nc),xytext=(7,6),textcoords="offset points",fontsize=10,color=c)
for k,nm in CTRL.items():
    if k in set(bd.locus):
        r=bd[bd.locus==k].iloc[0]; a.scatter(r.GC3,r.Nc,s=38,color="#444444",zorder=4)
        a.annotate(nm,(r.GC3,r.Nc),xytext=(4,-11),textcoords="offset points",fontsize=7,color="#444444")
a.set_xlabel("GC at third codon position (%)"); a.set_ylabel("effective number of codons, Nc")
a.set_title("Wright plot, lower Nc means stronger codon bias",fontsize=10)
plt.tight_layout(); plt.show()
